CREATE DATABASE IF NOT EXISTS payme CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE payme;
CREATE TABLE users (id CHAR(36) PRIMARY KEY, full_name VARCHAR(160) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, phone VARCHAR(40) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, kyc_status ENUM('pending','verified','rejected') NOT NULL DEFAULT 'pending', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE wallets (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, currency CHAR(10) NOT NULL, balance DECIMAL(24,8) NOT NULL DEFAULT 0, status ENUM('active','frozen') NOT NULL DEFAULT 'active', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_user_currency (user_id,currency), FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE transactions (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, type ENUM('send','receive','top_up','withdraw','exchange','payment') NOT NULL, provider VARCHAR(40) NOT NULL DEFAULT 'internal', amount DECIMAL(24,8) NOT NULL, currency CHAR(10) NOT NULL, counterparty VARCHAR(255), status ENUM('pending','completed','failed','reversed') NOT NULL DEFAULT 'pending', external_reference VARCHAR(120), idempotency_key VARCHAR(120), metadata JSON, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_user_idempotency (user_id,idempotency_key), INDEX ix_transaction_user_created (user_id,created_at), FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE payment_requests (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, provider VARCHAR(40) NOT NULL, amount DECIMAL(24,8) NOT NULL, currency CHAR(10) NOT NULL, phone VARCHAR(40), external_reference VARCHAR(120) NOT NULL UNIQUE, status ENUM('pending','completed','failed','cancelled') NOT NULL DEFAULT 'pending', provider_payment_id VARCHAR(160), payload JSON, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE idempotency_keys (user_id CHAR(36) NOT NULL, idempotency_key VARCHAR(120) NOT NULL, response_code SMALLINT NOT NULL, response_body JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,idempotency_key), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
